using System.Text;
using System.Text.Json;
namespace TutorFlow.Api.Tests;

public sealed class Registrador : DelegatingHandler
{
    public Registrador() : base(new HttpClientHandler()) { }
    public List<(string Req, string Res)> Pares { get; } = [];
    protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken ct)
    {
        var req = request.Content is null ? "" : await request.Content.ReadAsStringAsync(ct);
        var res = await base.SendAsync(request, ct);
        var cuerpo = await res.Content.ReadAsStringAsync(ct);
        Pares.Add((req, cuerpo));
        res.Content = new StringContent(cuerpo, Encoding.UTF8, "application/json");
        return res;
    }
}

